 17| /// Validate the config at `path`, printing a report.
 18| ///
 19| /// Returns an error when the config is unusable, so the process exits non-zero
 20| /// and CI fails.
 21| pub fn check(path: &Path) -> Result<()> {
 22|     let (root, explicit) = split_target(path);
 23|     let loaded = config::load(&root, explicit.as_deref())?;
 24|     let problems = config::validate::validate(&loaded.config);
 25| 
 26|     let where_from = loaded
 27|         .source
 28|         .as_ref()
 29|         .map(|p| p.display().to_string())
 30|         .unwrap_or_else(|| "built-in defaults (no config file found)".to_string());
 31| 
 32|     if problems.is_empty() {
 33|         println!("ok  {where_from}");
 34|         if let Some(preset) = &loaded.preset_source {
 35|             println!("    preset: {}", preset.display());
 36|         }
 37|         let lanes = loaded.config.enabled_lanes();
 38|         println!(
 39|             "    {} lane{}: {}",
 40|             lanes.len(),
 41|             if lanes.len() == 1 { "" } else { "s" },
 42|             lanes
 43|                 .iter()
 44|                 .map(|l| l.as_str())
 45|                 .collect::<Vec<_>>()
 46|                 .join(", ")
 47|         );
 48|         return Ok(());
 49|     }
 50| 
 51|     println!("{where_from}");
 52|     for problem in &problems {
 53|         println!("  - {problem}");
 54|     }
 55| 
 56|     Err(Error::config(format!(
 57|         "{} problem{} found",
 58|         problems.len(),
 59|         if problems.len() == 1 { "" } else { "s" }
 60|     )))
 61| }
 62| 
 63| /// Report the effective configuration and where each value came from.
 64| pub fn doctor(path: &Path, as_json: bool) -> Result<()> {
 65|     let (root, explicit) = split_target(path);
 66|     let loaded = config::load(&root, explicit.as_deref())?;
 67| 
 68|     if as_json {
 69|         print_json(&loaded)?;
 70|     } else {
 71|         print_prose(&loaded);
 72|     }
 73| 
 74|     Ok(())
 75| }
 76| 
 77| fn print_json(loaded: &Loaded) -> Result<()> {
 78|     let provenance: serde_json::Map<String, serde_json::Value> = loaded
 79|         .provenance
 80|         .iter()
 81|         .map(|(key, layer)| (key.to_string(), json!(layer.as_str())))
 82|         .collect();
 83| 
 84|     let report = json!({
 85|         "source": loaded.source.as_ref().map(|p| p.display().to_string()),
 86|         "preset": loaded.preset_source.as_ref().map(|p| p.display().to_string()),
 87|         "config": redacted_config(&loaded.config)?,
 88|         "provenance": provenance,
 89|         "problems": config::validate::validate(&loaded.config),
 90|         "credentials": credentials(loaded),
 91|     });
 92| 
 93|     println!("{}", serde_json::to_string_pretty(&report)?);
 94|     Ok(())
 95| }
 96| 
 97| /// Serialize the config with credential-bearing fields redacted.
 98| ///
 99| /// `models.api_key_env` and `sentry.token_env` are supposed to hold the *name*
100| /// of an environment variable. When someone pastes the key itself — the exact
101| /// mistake validation warns about — serializing the config verbatim prints that
102| /// key into a terminal or a CI log. `doctor --json` is often the first thing
103| /// run when something is wrong, so it is precisely the wrong moment to echo a
104| /// credential.
105| fn redacted_config(config: &Config) -> Result<serde_json::Value> {
106|     let mut value = serde_json::to_value(config)?;
107| 
108|     for (section, field) in [("models", "api_key_env"), ("sentry", "token_env")] {
109|         if let Some(current) = value
110|             .get_mut(section)
111|             .and_then(|s| s.get_mut(field))
112|             .and_then(|f| f.as_str().map(str::to_string))
113|             && looks_like_a_value(&current)
114|         {
115|             value[section][field] = json!(crate::scan::types::redact(&current));
116|         }
117|     }
118| 
119|     Ok(value)
120| }
121| 
122| /// Whether a field that should name an environment variable holds something
123| /// else. Environment variable names are conventionally SCREAMING_SNAKE_CASE, so
124| /// a lowercase letter is the cheap tell that a value was pasted instead.
125| fn looks_like_a_value(text: &str) -> bool {
126|     text.contains(|c: char| c.is_ascii_lowercase())
127| }
128| 
129| fn print_prose(loaded: &Loaded) {
130|     let config = &loaded.config;
131| 
132|     println!("config");
133|     println!(
134|         "  file    {}",
135|         loaded
136|             .source
137|             .as_ref()
138|             .map(|p| p.display().to_string())
139|             .unwrap_or_else(|| "<none — running on built-in defaults>".into())
140|     );
141|     if let Some(preset) = &loaded.preset_source {
142|         println!("  preset  {}", preset.display());
143|     }
144| 
145|     println!("\nreview");
146|     println!(
147|         "  lanes            {}",
148|         config
149|             .enabled_lanes()
150|             .iter()
151|             .map(|l| l.as_str())
152|             .collect::<Vec<_>>()
153|             .join(", ")
154|     );
155|     println!(
156|         "  strictness       {}  ({})",
157|         config.review.strictness,
158|         crate::config::types::Strictness::for_level(config.review.strictness).label
159|     );
160|     println!(
161|         "  severity gate    {}{}",
162|         config.severity_gate(),
163|         if config.review.severity_gate.is_some() {
164|             "  (set explicitly)"
165|         } else {
166|             ""
167|         }
168|     );
169|     println!(
170|         "  confidence min   {}{}",
171|         config.confidence_min(),
172|         if config.review.confidence_min.is_some() {
173|             "  (set explicitly)"
174|         } else {
175|             ""
176|         }
177|     );
178|     println!("  max comments     {}", config.review.max_comments);
179|     println!("  incremental      {}", config.review.incremental);
180| 
181|     println!("\nmodels");
182|     println!("  gateway          {}", config.models.gateway);
183|     println!("  base url         {}", config.models.base_url);
184|     println!("  scan tier        {}", config.models.scan);
185|     println!("  deep tier        {}", config.models.deep);
186|     println!("  budget per PR    ${:.2}", config.models.budget_usd_per_pr);
187|     for lane in config.enabled_lanes() {
188|         println!(
189|             "  {:<16} {}  (fails at {})",
190|             lane.as_str(),
191|             config.model_for(lane),
192|             config.fail_on(lane)
193|         );
194|     }
195| 
196|     // A model with no price is billed at the ceiling, so it will not escape the
197|     // budget — but it will over-report, and the fix is a one-line table entry.
198|     // Saying so here is what makes a stale price table visible before a review
199|     // runs rather than after it has been billed.
200|     let configured: Vec<&str> = config
201|         .enabled_lanes()
202|         .into_iter()
203|         .map(|lane| config.model_for(lane))
204|         .chain([config.models.scan.as_str(), config.models.deep.as_str()])
205|         .chain(config.models.fallback.iter().map(String::as_str))

