 1| //! The chunker: pick spans, hash them, hand back indexable chunks.
 2| //!
 3| //! Always compiled. With `treesitter` on it tries the grammar first and falls
 4| //! back to the line splitter; with it off every file takes the fallback. Either
 5| //! way the resulting chunk says which happened, so nothing downstream has to
 6| //! infer it from the build flags.
 7| 
 8| use sha2::{Digest, Sha256};
 9| 
10| use crate::chunk::lang::{self, Language};
11| use crate::chunk::lines;
12| use crate::chunk::types::{ChunkOptions, SkipReason, SourceChunk};
13| use crate::index::types::Chunk;
14| 
15| /// Turns a file's text into chunks.
16| #[derive(Debug, Clone, Default)]
17| pub struct Chunker {
18|     options: ChunkOptions,
19| }
20| 
21| impl Chunker {
22|     /// A chunker with the default sizes.
23|     pub fn new() -> Self {
24|         Self::default()
25|     }
26| 
27|     /// A chunker with caller-chosen sizes.
28|     pub fn with_options(options: ChunkOptions) -> Self {
29|         Self { options }
30|     }
31| 
32|     /// The sizes this chunker was built with.
33|     pub fn options(&self) -> ChunkOptions {
34|         self.options
35|     }
36| 
37|     /// Choose the spans of one file.
38|     ///
39|     /// The grammar is tried first and the line splitter is the fallback, not a
40|     /// competitor: a file the grammar declines is still worth indexing, it just
41|     /// does not get to claim its chunks contain whole definitions.
42|     pub fn spans(&self, path: &str, source: &str) -> Vec<SourceChunk> {
43|         #[cfg(feature = "treesitter")]
44|         if let Some(language) = Language::from_path(path)
45|             && let Some(chunks) = crate::chunk::tree::split(source, language, &self.options)
46|         {
47|             return chunks;
48|         }
49| 
50|         // Referenced so the `treesitter`-off build does not warn about an
51|         // unused import, and so the two builds read the same.
52|         let _ = Language::from_path(path);
53|         lines::split(source, 1, &self.options)
54|     }
55| 
56|     /// Chunk one file into index-ready values.
57|     pub fn chunk(&self, repo_id: &str, path: &str, source: &str) -> Vec<Chunk> {
58|         let language = Language::from_path(path).map(|l| l.as_str().to_string());
59|         // A file no grammar claims still gets a language label from its
60|         // extension. Reporting `None` would make every `.sql` hit look like a
61|         // file of unknown type rather than one we chose not to parse.
62|         let label = language.or_else(|| lang::fallback_label(path));

