  1| //! Mapping a path to a language, and the extension allowlist.
  2| //!
  3| //! Always compiled. [`Language`] names a *grammar* we may have, not a family of
  4| //! files: TSX and TypeScript are separate because tree-sitter ships two
  5| //! grammars and parsing one with the other fails on the first JSX element.
  6| //!
  7| //! The allowlist is separate from the grammar list on purpose. Plenty of files
  8| //! are worth retrieving — Markdown, TOML, SQL, Java — that we cannot parse. They
  9| //! are indexed through the line splitter and say so in their metadata, which is
 10| //! strictly better than being invisible.
 11| 
 12| use std::path::Path;
 13| 
 14| /// A language the chunker recognises.
 15| #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
 16| pub enum Language {
 17|     /// Rust.
 18|     Rust,
 19|     /// TypeScript without JSX.
 20|     TypeScript,
 21|     /// TypeScript with JSX.
 22|     Tsx,
 23|     /// JavaScript, including JSX — one grammar covers both.
 24|     JavaScript,
 25|     /// Python.
 26|     Python,
 27|     /// Go.
 28|     Go,
 29| }
 30| 
 31| impl Language {
 32|     /// The language of `path`, when there is a grammar for it.
 33|     ///
 34|     /// `None` means the line splitter handles the file, not that the file is
 35|     /// uninteresting — see [`is_indexable`].
 36|     pub fn from_path(path: &str) -> Option<Self> {
 37|         match extension(path).as_str() {
 38|             "rs" => Some(Self::Rust),
 39|             "ts" | "mts" | "cts" => Some(Self::TypeScript),
 40|             "tsx" => Some(Self::Tsx),
 41|             "js" | "mjs" | "cjs" | "jsx" => Some(Self::JavaScript),
 42|             "py" | "pyi" => Some(Self::Python),
 43|             "go" => Some(Self::Go),
 44|             _ => None,
 45|         }
 46|     }
 47| 
 48|     /// The stable name written onto a chunk's `lang` field.
 49|     pub fn as_str(self) -> &'static str {
 50|         match self {
 51|             Self::Rust => "rust",
 52|             Self::TypeScript => "typescript",
 53|             Self::Tsx => "tsx",
 54|             Self::JavaScript => "javascript",
 55|             Self::Python => "python",
 56|             Self::Go => "go",
 57|         }
 58|     }
 59| 
 60|     /// Every language with a grammar, for tests and for `--help` text.
 61|     pub const ALL: [Language; 6] = [
 62|         Language::Rust,
 63|         Language::TypeScript,
 64|         Language::Tsx,
 65|         Language::JavaScript,
 66|         Language::Python,
 67|         Language::Go,
 68|     ];
 69| }
 70| 
 71| /// The lowercase extension of `path`, without the dot. Empty when there is none.
 72| pub fn extension(path: &str) -> String {
 73|     Path::new(path)
 74|         .extension()
 75|         .and_then(|e| e.to_str())
 76|         .unwrap_or_default()
 77|         .to_ascii_lowercase()
 78| }
 79| 
 80| /// The label written onto a chunk when no grammar claims the file.
 81| ///
 82| /// The extension itself, so a retrieval hit in a `.sql` file still says `sql`.
 83| /// `None` for an extensionless file rather than a guess.
 84| pub fn fallback_label(path: &str) -> Option<String> {
 85|     let extension = extension(path);
 86|     (!extension.is_empty()).then_some(extension)
 87| }
 88| 
 89| /// Extensions indexed by default, beyond the ones with grammars.
 90| ///
 91| /// Kept as a list rather than "everything that is not binary" because an
 92| /// allowlist fails towards indexing too little, and indexing too much is the
 93| /// expensive direction: minified bundles, lockfiles and generated clients are
 94| /// enormous, embed for real money, and are never the answer to a review query.
 95| pub const EXTRA_EXTENSIONS: &[&str] = &[
 96|     "c", "cc", "cpp", "cs", "h", "hpp", "java", "kt", "kts", "swift", "rb", "php", "scala", "sh",
 97|     "bash", "zsh", "sql", "proto", "graphql", "gql", "tf", "md", "mdx", "rst", "toml", "yaml",
 98|     "yml", "json", "css", "scss", "html", "vue", "svelte", "lua", "ex", "exs", "erl", "hs", "ml",
 99|     "r", "pl", "dart", "zig",
100| ];
101| 
102| /// Whether a path's extension is on the allowlist.
103| pub fn is_indexable(path: &str) -> bool {
104|     if Language::from_path(path).is_some() {
105|         return true;
106|     }
107|     let extension = extension(path);
108|     !extension.is_empty() && EXTRA_EXTENSIONS.contains(&extension.as_str())
109| }
110| 
