  1| //! The fallback splitter: line boundaries, no grammar.
  2| //!
  3| //! Always compiled. Used for files no grammar claims, and for the rare
  4| //! definition too large to keep whole. Every chunk it produces is marked
  5| //! [`ChunkMethod::Lines`](crate::index::types::ChunkMethod::Lines), which is the
  6| //! honest part: these spans may well begin halfway through a function.
  7| //!
  8| //! Two decisions worth stating.
  9| //!
 10| //! **No overlap.** Repeating the last few lines of one chunk at the head of the
 11| //! next is a cheap imitation of context, and it costs real money — every
 12| //! duplicated line is embedded twice and stored twice — while making dedupe
 13| //! harder, because two chunks now legitimately share text. The grammar path
 14| //! makes overlap unnecessary; on this path it would only paper over the split.
 15| //!
 16| //! **A long line is never cut.** A minified bundle would otherwise be sliced
 17| //! mid-token into spans that mean nothing. The chunk goes over the target
 18| //! instead, and the file-size cap in [`select`](crate::chunk::select) is what
 19| //! keeps that bounded.
 20| 
 21| use crate::chunk::types::{ChunkOptions, SourceChunk};
 22| use crate::index::types::ChunkMethod;
 23| 
 24| /// Split `text` on line boundaries.
 25| ///
 26| /// `first_line` is the 1-based line number of `text`'s first line, so this can
 27| /// split a fragment of a file — an oversized function body, say — and still
 28| /// report line numbers in the file's own coordinates.
 29| pub fn split(text: &str, first_line: u32, options: &ChunkOptions) -> Vec<SourceChunk> {
 30|     let mut chunks = Vec::new();
 31|     let mut buffer = String::new();
 32|     let mut buffer_start = first_line;
 33|     let mut line_number = first_line;
 34| 
 35|     for line in text.split_inclusive('\n') {
 36|         // A blank line is the only structural hint available without a grammar,
 37|         // so a chunk that is already substantial ends at one rather than at an
 38|         // arbitrary character count part-way through a paragraph of code.
 39|         let blank = line.trim().is_empty();
 40|         // A buffer holding only blank lines is never flushed: it would be
 41|         // dropped as whitespace and those lines would vanish from the file the
 42|         // chunks reconstruct. It keeps accumulating instead, and the blank run
 43|         // ends up at the head of the next real chunk.
 44|         let flushable = !buffer.trim().is_empty();
 45|         let would_exceed = flushable && buffer.len() + line.len() > options.target_chars;
 46|         let at_a_seam = flushable && blank && buffer.len() >= options.target_chars / 2;
 47| 
 48|         if would_exceed || at_a_seam {
 49|             push(&mut chunks, &mut buffer, buffer_start, line_number - 1);
 50|             buffer_start = line_number;
 51|         }
 52| 
 53|         buffer.push_str(line);
 54|         line_number += 1;
 55|     }
 56| 
 57|     push(&mut chunks, &mut buffer, buffer_start, line_number - 1);
 58|     chunks
 59| }
 60| 
 61| fn push(chunks: &mut Vec<SourceChunk>, buffer: &mut String, start_line: u32, end_line: u32) {
 62|     if buffer.trim().is_empty() {
 63|         // Whitespace-only spans are dropped rather than emitted: embedding them
 64|         // costs money and they can never be the right answer to a query.
 65|         buffer.clear();
 66|         return;
 67|     }
 68|     chunks.push(SourceChunk {
 69|         start_line,
 70|         end_line: end_line.max(start_line),
 71|         text: std::mem::take(buffer),
 72|         symbol: None,
 73|         method: ChunkMethod::Lines,
 74|     });
 75| }
 76| 
 77| #[cfg(test)]
 78| mod tests {
 79|     use super::*;
 80| 
 81|     fn options(target: usize) -> ChunkOptions {
 82|         ChunkOptions::with_target(target)
 83|     }
 84| 
 85|     #[test]
 86|     fn line_numbers_are_contiguous_and_cover_the_input() {
 87|         let text: String = (1..=200).map(|i| format!("line {i}\n")).collect();
 88|         let chunks = split(&text, 1, &options(120));
 89| 
 90|         assert!(chunks.len() > 1, "the input should not fit in one chunk");
 91|         assert_eq!(chunks[0].start_line, 1);
 92|         assert_eq!(chunks.last().expect("a chunk").end_line, 200);
 93|         for pair in chunks.windows(2) {
 94|             assert_eq!(
 95|                 pair[1].start_line,
 96|                 pair[0].end_line + 1,
 97|                 "chunks must tile the file without gaps or overlap"
 98|             );
 99|         }
100|     }
101| 
102|     #[test]
103|     fn the_concatenated_chunks_reproduce_the_input() {
104|         // A splitter that loses or duplicates a line is worse than no index at
105|         // all, because the loss is invisible at query time.
106|         let text = "alpha\nbeta\n\ngamma\ndelta\n\nepsilon\n";
107|         let rejoined: String = split(text, 1, &options(8))
108|             .iter()
109|             .map(|c| c.text.clone())
110|             .collect();
111|         assert_eq!(rejoined, text);
112|     }
113| 
114|     #[test]

