  1| //! Rendering the diff for a model, and splitting it into what was already
  2| //! reviewed and what is new.
  3| //!
  4| //! The rendering lives here rather than in a lane because two callers need the
  5| //! *same bytes*: the lane, which sends them, and `review`, which stores them so
  6| //! the next cycle can replay them. Prompt layer 3 only pays if the replay is
  7| //! byte-identical (see `crate::harness::prompt`), and two independent renderers
  8| //! would drift apart on the first formatting change and silently cost every
  9| //! re-review full input price.
 10| //!
 11| //! The split is per file. A file whose rendered block is unchanged since the
 12| //! last review has already been reviewed, so it goes in the cacheable prefix;
 13| //! anything else is the delta and goes in the volatile suffix. Per file rather
 14| //! than per commit because a pull request diff is what the forge gives us —
 15| //! there is no local checkout to compute a commit range against.
 16| 
 17| use crate::evidence::diff::FileDiff;
 18| 
 19| /// The marker that opens a file's block in rendered evidence.
 20| const FILE_PREFIX: &str = "--- ";
 21| 
 22| /// Render diffs into the text a model sees.
 23| ///
 24| /// Line numbers are included because models anchor badly when left to count,
 25| /// and a finding anchored to the wrong line is a comment on somebody else's
 26| /// code.
 27| pub fn render(diffs: &[FileDiff]) -> String {
 28|     // Delegates rather than duplicates. This was a second, byte-identical copy
 29|     // of `diff::render`, which is precisely the drift this module's own doc
 30|     // comment warns about: the moment the two disagreed by one space, every
 31|     // replay would stop matching and every re-review would silently pay full
 32|     // input price with nothing to show for it.
 33|     crate::evidence::diff::render(diffs)
 34| }
 35| 
 36| /// Split `current` into the part `previous` already contained, and the rest.
 37| ///
 38| /// A block is "already reviewed" only when it matches byte for byte: a file
 39| /// that gained one line since the last review is new work in its entirety,
 40| /// because the model cannot be shown half a hunk. Returns `("", current)` when
 41| /// there is nothing to replay, which is the first-review case.
 42| pub fn split(previous: &str, current: &str) -> (String, String) {
 43|     if previous.trim().is_empty() {
 44|         return (String::new(), current.to_string());
 45|     }
 46| 
 47|     let seen: Vec<&str> = blocks(previous);
 48|     let mut reviewed = String::new();
 49|     let mut fresh = String::new();
 50| 
 51|     for block in blocks(current) {
 52|         if seen.contains(&block) {
 53|             reviewed.push_str(block);
 54|         } else {
 55|             fresh.push_str(block);
 56|         }
 57|     }
 58| 
 59|     // Everything already reviewed and nothing new: replaying it as the prefix
 60|     // would leave the model with an empty task. Send it as the work instead —
 61|     // this is a re-run of the same commit, not an increment.
 62|     if fresh.trim().is_empty() {
 63|         return (String::new(), current.to_string());
 64|     }
 65| 
 66|     (reviewed, fresh)
 67| }
 68| 
 69| /// Which of `diffs` a previous review has already seen, byte for byte.
 70| ///
 71| /// The same rule as [`split`], asked per file instead of over one string: a
 72| /// file whose rendered block is identical to one in `previous` was reviewed and
 73| /// has not changed since.
 74| ///
 75| /// This is what lets a per-file lane skip work rather than merely cache it.
 76| /// `split` moves already-reviewed bytes into the cacheable prefix, which only
 77| /// pays when the provider honours the cache; skipping the file entirely pays
 78| /// always, because the cheapest call is the one not made.
 79| ///
 80| /// Returns everything as unreviewed when `previous` is empty — the first-review
 81| /// case — so a caller can use this unconditionally.
 82| pub fn unreviewed<'a>(previous: &str, diffs: &'a [FileDiff]) -> Vec<&'a FileDiff> {
 83|     if previous.trim().is_empty() {
 84|         return diffs.iter().collect();
 85|     }
 86| 
 87|     let seen = blocks(previous);
 88| 
 89|     let fresh: Vec<&FileDiff> = diffs
 90|         .iter()
 91|         .filter(|diff| {
 92|             // Rendered one file at a time, through the same function that
 93|             // produced `previous`. Comparing anything other than the exact
 94|             // bytes both sides emit would drift on the first formatting change
 95|             // and silently start re-reviewing everything.
 96|             let block = render(std::slice::from_ref(*diff));
 97|             !block.is_empty() && !seen.contains(&block.as_str())
 98|         })
 99|         .collect();
100| 
101|     // Nothing new: this is a re-run of the same commit rather than an
102|     // increment, and returning an empty list would make the lane report that a
103|     // pull request has no attack surface. Same reasoning as `split`.

