 29| impl MockModel {
 30|     /// A model with no responses queued. Calling it is an error.
 31|     pub fn new() -> Self {
 32|         Self::default()
 33|     }
 34| 
 35|     /// A model that answers every call with `value`.
 36|     pub fn always(value: Value) -> Self {
 37|         Self {
 38|             responses: Arc::new(Mutex::new(vec![])),
 39|             requests: Arc::new(Mutex::new(vec![])),
 40|             usage: Usage::default(),
 41|             answers_as: None,
 42|         }
 43|         .repeating(value)
 44|     }
 45| 
 46|     /// A model that reports no findings.
 47|     pub fn silent() -> Self {
 48|         Self::always(json!({"summary": "Nothing to report.", "findings": []}))
 49|     }
 50| 
 51|     /// Queue one response. Responses are consumed in order.
 52|     pub fn then(self, value: Value) -> Self {
 53|         self.responses
 54|             .lock()
 55|             .expect("mock model lock")
 56|             .push(Ok(value));
 57|         self
 58|     }
 59| 
 60|     /// Queue a failure.
 61|     pub fn then_error(self, message: &str) -> Self {
 62|         self.responses
 63|             .lock()
 64|             .expect("mock model lock")
 65|             .push(Err(Error::Model(message.to_string())));
 66|         self
 67|     }
 68| 
 69|     /// Answer as `model` whatever model was asked for.
 70|     ///
 71|     /// This is what a provider fallback looks like from the port: the request
 72|     /// named one model and a different one came back. Tests use it to prove the
 73|     /// cost line reports what answered rather than what was configured.
 74|     pub fn answering_as(mut self, model: impl Into<String>) -> Self {
 75|         self.answers_as = Some(model.into());
 76|         self
 77|     }
 78| 
 79|     /// Report `usage` on every call, so budget enforcement is testable.
 80|     pub fn with_usage(mut self, usage: Usage) -> Self {
 81|         self.usage = usage;
 82|         self
 83|     }
 84| 
 85|     /// Every request the model received, in order.
 86|     pub fn requests(&self) -> Vec<ModelRequest> {
 87|         self.requests.lock().expect("mock model lock").clone()
 88|     }
 89| 
 90|     /// How many times it was called.
 91|     pub fn calls(&self) -> usize {
 92|         self.requests.lock().expect("mock model lock").len()
 93|     }
 94| 
 95|     /// The concatenated text of the last request, for prompt assertions.
 96|     pub fn last_prompt(&self) -> Option<String> {
 97|         self.requests().last().map(|request| {
 98|             request
 99|                 .messages
100|                 .iter()
101|                 .map(|m| m.content.as_str())
102|                 .collect::<Vec<_>>()
103|                 .join("\n")
104|         })
105|     }
