120| #[async_trait]
121| impl Model for MockModel {
122|     async fn complete(&self, request: ModelRequest) -> Result<ModelResponse> {
123|         let model = self
124|             .answers_as
125|             .clone()
126|             .unwrap_or_else(|| request.model.clone());
127|         self.requests.lock().expect("mock model lock").push(request);
128| 
129|         let queued = {
130|             let mut responses = self.responses.lock().expect("mock model lock");
131|             if responses.is_empty() {
132|                 None
133|             } else {
134|                 Some(responses.remove(0))
135|             }
136|         };
137| 
138|         match queued {
139|             Some(Ok(value)) => Ok(ModelResponse {
140|                 value,
141|                 model,
142|                 usage: self.usage,
143|             }),
144|             Some(Err(err)) => Err(err),
145|             None => Err(Error::Model(
146|                 "MockModel ran out of queued responses; queue one with `.then(…)`".into(),
147|             )),
148|         }
149|     }
150| }
