179| /// The run this call is made from, carrying the configured output ceiling.
180| ///
181| /// `models.max_tokens` reaches the provider as the run's per-turn output cap
182| /// rather than as a field on the request: the agent loop builds the provider
183| /// request itself, and `RunConfig::max_turn_output_tokens` is the documented
184| /// hook it applies before dispatching. Setting it on a request we do not own
185| /// would be discarded — which is exactly what used to happen to this setting.
186| ///
187| /// The loop lowers, never raises: it takes the minimum of this cap and any cap
188| /// the request already carries, and its truncated-empty retry may still grow
189| /// the budget from here. Both are wanted — the ceiling is protection against a
190| /// runaway answer, not a demand for one.
191| fn run_config(request: &ModelRequest) -> RunConfig {
192|     let config = RunConfig::new("tinysweeper-lane");
193|     // `config::validate` rejects `max_tokens = 0`, but a `Config` built in code
194|     // can carry it, and forwarding a zero cap asks the provider for an empty
195|     // answer on every lane. Leave the ceiling off rather than guarantee failure.
196|     if request.max_tokens == 0 {
197|         return config;
198|     }
199|     config.with_max_turn_output_tokens(request.max_tokens)
200| }
