202| #[async_trait]
203| impl Model for GatewayModel {
204|     async fn complete(&self, request: ModelRequest) -> Result<ModelResponse> {
205|         let mut last = match self.call(&request.model, &request).await {
206|             Ok(response) => return Ok(response),
207|             Err(err) => err,
208|         };
209| 
210|         // Fallbacks exist because a single provider outage should degrade the
211|         // review rather than fail the check. The model that actually answered
212|         // is reported back so the summary can say so.
213|         for fallback in &self.fallbacks {
214|             tracing::warn!(
215|                 primary = %request.model,
216|                 fallback = %fallback,
217|                 error = %last,
218|                 "model call failed; trying the next model"
219|             );
220|             match self.call(fallback, &request).await {
221|                 Ok(response) => return Ok(response),
222|                 Err(err) => last = err,
223|             }
224|         }
225| 
226|         Err(last)
227|     }
228| }
