160| /// The price of `model`, when it is known.
161| pub fn price_of(model: &str) -> Option<Price> {
162|     MODEL_PRICES
163|         .iter()
164|         .find(|(id, _)| *id == model)
165|         .map(|(_, price)| *price)
166| }
