168| /// Which of `models` this build has no price for.
169| ///
170| /// Reported by `doctor` so a stale table is visible before a review runs,
171| /// rather than after it has been billed at the ceiling.
172| pub fn unpriced<'a>(models: impl IntoIterator<Item = &'a str>) -> Vec<String> {
173|     models
174|         .into_iter()
175|         .filter(|model| price_of(model).is_none())
176|         .map(str::to_string)
177|         .collect()
178| }
