180| /// The most expensive rate in the table, charged for an unpriced model.
181| ///
182| /// Each component is maximised independently. The point is an upper bound on
183| /// spend, not a plausible price list.
184| pub fn ceiling() -> Price {
185|     MODEL_PRICES.iter().fold(
186|         Price {
187|             input: 0.0,
188|             output: 0.0,
189|             cached: 0.0,
190|         },
191|         |mut worst, (_, price)| {
192|             worst.input = worst.input.max(price.input);
193|             worst.output = worst.output.max(price.output);
194|             worst.cached = worst.cached.max(price.cached);
195|             worst
196|         },
197|     )
198| }
199| 
200| /// What one completion cost, in USD.
201| ///
202| /// `input_tokens` includes `cached_tokens`, exactly as providers report it.
203| pub fn completion_cost(
204|     model: &str,
205|     input_tokens: u64,
206|     cached_tokens: u64,
207|     output_tokens: u64,
208| ) -> f64 {
209|     let price = price_of(model).unwrap_or_else(|| {
210|         tracing::warn!(
211|             model,
212|             "no price known for this model; billing it at the most expensive rate in the table so \
213|              it still counts against the budget"
214|         );
215|         ceiling()
216|     });
217| 
218|     // Cached input tokens are billed at the cache-read rate, not the input
219|     // rate, and on kimi-k3 that is a tenfold difference — charging them at full
220|     // price would make every re-review look ten times more expensive than it is.
221|     let fresh_input = input_tokens.saturating_sub(cached_tokens);
222|     let million = 1_000_000.0;
223| 
224|     (fresh_input as f64 * price.input
225|         + cached_tokens as f64 * price.cached
226|         + output_tokens as f64 * price.output)
227|         / million
228| }
229| 
230| /// What embedding `tokens` cost, in USD.
231| ///
232| /// `signature` is the embedder's `provider/model`. An unknown embedder is
233| /// charged the most expensive embedding rate for the same reason an unknown
234| /// completion model is: indexing a repository is the largest token count this
235| /// program produces, and it must not be the one that escapes the budget.
236| pub fn embedding_cost(signature: &str, tokens: u64) -> f64 {
237|     // A locally served model is not billed by anybody, and listing every GGUF
238|     // somebody might run behind Ollama is a table nobody can keep current. The
239|     // rule is the provider, not the model: `ollama` means the vectors were
240|     // computed on this machine, and charging the ceiling for that would make
241|     // the budget stop a run that costs nothing.
242|     if signature.starts_with("ollama/") {
243|         return 0.0;
244|     }
245| 
246|     let per_million = EMBED_PRICES
247|         .iter()
248|         .find(|(id, _)| *id == signature)
249|         .map(|(_, price)| *price)
250|         .unwrap_or_else(|| {
251|             let worst = EMBED_PRICES
252|                 .iter()
253|                 .fold(0.0_f64, |worst, (_, price)| worst.max(*price));
254|             tracing::warn!(
255|                 signature,
256|                 "no price known for this embedder; billing it at the most expensive embedding rate"
257|             );
258|             worst
259|         });
260| 
261|     tokens as f64 * per_million / 1_000_000.0
262| }
263| 
264| /// A rough token count for text about to be embedded.
265| ///
266| /// Four bytes per token is the usual approximation for code and English prose,
267| /// and it is what the estimate has to be: embedding providers report usage only
268| /// in the response, and the budget has to be checked before the call as well as
269| /// after it. It rounds up, so the estimate never under-charges.
270| pub fn estimate_tokens(text: &str) -> u64 {
271|     text.len().div_ceil(4) as u64
272| }
