31| ///
32| /// The forge returns them most-recently-updated first, so this is a recency
33| /// window rather than a sample: a duplicate of something nobody has touched in
34| /// two years is not what triage is for.
35| pub const SCAN_LIMIT: usize = 200;
36| 
37| /// How many candidates are put in front of the model.
38| pub const MAX_CANDIDATES: usize = 5;
