41| #[derive(Debug, Clone)]
42| pub struct TriageOutcome {
43|     /// What deterministic code decided to do. The only thing `apply` reads.
44|     pub plan: TriagePlan,
45|     /// What the model said. Advisory, kept for the log and for tests.
46|     pub verdict: IssueVerdict,
