53| /// Triage one issue and return a plan. Writes nothing.
54| pub async fn triage(
55|     forge: &dyn ForgeRead,
56|     model: Arc<dyn Model>,
57|     config: &Config,
58|     repo: &RepoId,
59|     number: u64,
60|     maintainers: &[String],
61| ) -> Result<TriageOutcome> {
62|     let policy = &config.issues;
63|     if !policy.enabled {
64|         return Ok(skipped("issues.enabled is off"));
65|     }
66| 
67|     let issue = forge.issue(repo, number).await?;
68|     if !issue.open {
69|         return Ok(skipped("the issue is already closed"));
