73|     // only ones the close gate will later accept. Everything downstream of here
74|     // is bounded by this list.
75|     let candidates = if policy.dedupe {
76|         let others = forge.open_issues(repo, SCAN_LIMIT).await?;
77|         dedupe::shortlist(&issue, &others, MAX_CANDIDATES)
