85|             model: config.model_for_issues().to_string(),
86|             messages: vec![
87|                 Message::system(prompt::SYSTEM),
88|                 Message::user(prompt::suffix(&issue, &comments, &candidates)),
89|             ],
90|             schema: prompt::schema(),
91|             schema_name: "tinysweeper_issue_triage".into(),
92|             max_tokens: config.models.max_tokens,

