322|     /// Extract rules from every scoped file at `head_sha`.
323|     ///
324|     /// Best-effort by construction: a file that cannot be fetched, a model that
325|     /// errors and an answer that fails validation all contribute nothing and
326|     /// none of them fail the review. Repository policy is an *improvement* to a
327|     /// review, and losing a review over it would be a worse outcome than
328|     /// reviewing without it — and a way for any contributor to break the bot.
329|     pub async fn extract(
330|         &self,
331|         forge: &dyn ForgeRead,
332|         repo: &RepoId,
333|         head_sha: &str,
334|         files: &[String],
335|     ) -> (Vec<String>, Usage) {
336|         let mut rules: Vec<String> = Vec::new();
337|         let mut usage = Usage::default();
338| 
339|         for path in files {
340|             let file = match self.fetch(forge, repo, head_sha, path).await {
341|                 Ok(Some(file)) => file,
342|                 Ok(None) => continue,
343|                 Err(err) => {
344|                     tracing::warn!(%err, %path, "could not read an instruction file");
345|                     continue;
346|                 }
347|             };
348| 
349|             if let Some(cached) = self.cache.get(&file.content_hash) {
350|                 tracing::debug!(%path, "extraction served from the content-hash cache");
351|                 merge(&mut rules, cached);
352|                 continue;
353|             }
354| 
355|             match self.extract_one(&file).await {
356|                 Ok((extracted, call_usage)) => {
357|                     usage.add(call_usage);
358|                     self.cache.put(&file.content_hash, extracted.clone());
359|                     merge(&mut rules, extracted);
360|                 }
361|                 Err(err) => tracing::warn!(%err, %path, "extraction failed; ignoring the file"),
362|             }
