382|         // function that turns a name into a request, so it is the function that
383|         // has to be safe on its own.
384|         if !crate::knowledge::types::valid_instruction_path(path) {
385|             tracing::warn!(%path, "refusing to fetch an instruction file with an unsafe path");
386|             return Ok(None);
387|         }
388| 
389|         let Some(content) = forge.file_at(repo, path, head_sha).await? else {
390|             return Ok(None);
391|         };
392|         let content = truncate_bytes(&content, self.max_bytes).to_string();
393|         if content.trim().is_empty() {
394|             return Ok(None);
395|         }
