404|     /// The model calls for one file. No review context, and at most
405|     /// [`EXTRACT_ATTEMPTS`] of them.
406|     ///
407|     /// The retry is on the *format*, never on the content: an answer that
408|     /// parses is taken as it stands, and so is the `NO_RULES` sentinel, which is
409|     /// a correct answer rather than a failed one. Asking again for a file that
410|     /// genuinely states no rules would pay a second call for the same "no".
411|     ///
412|     /// A model *error* is not retried here — the gateway already walks its
413|     /// fallback models — and it costs the file rather than the review.
414|     async fn extract_one(&self, file: &InstructionFile) -> Result<(Vec<String>, Usage)> {
415|         let mut usage = Usage::default();
416| 
417|         for attempt in 1..=EXTRACT_ATTEMPTS {
418|             let response = self.call(file).await?;
419|             usage.add(response.usage);
420| 
421|             let raw = response
422|                 .value
423|                 .get("rules_markdown")
424|                 .and_then(serde_json::Value::as_str)
425|                 .unwrap_or_default();
426| 
427|             let rules = parse_rules(raw);
428|             if !rules.is_empty() || raw.trim() == NO_RULES {
429|                 return Ok((rules, usage));
430|             }
431| 
432|             tracing::warn!(
433|                 path = %file.path,
434|                 attempt,
435|                 "an extraction was discarded; asking again"
436|             );
437|         }
438| 
439|         Ok((Vec::new(), usage))
440|     }
