 58|     async fn run(&self, input: LaneInput<'_>) -> Result<LaneOutcome> {
 59|         // Cheapest possible check first. A pull request that only deletes
 60|         // files, or only touches ignored paths, has nothing for this lane, and
 61|         // asking a model to confirm that is money for a foregone conclusion.
 62|         if !input.has_reviewable_content() {
 63|             return Ok(LaneOutcome::skipped(
 64|                 "No added or modified lines to review.",
 65|             ));
 66|         }
 67| 
 68|         if input.pull_request.draft && !input.config.review.draft_prs {
 69|             return Ok(LaneOutcome::skipped(
 70|                 "Draft pull request; set `review.draft_prs = true` to review drafts.",
 71|             ));
 72|         }
 73| 
 74|         // Put the initial complete diff in the same serialized prefix where a
 75|         // later run replays it. Providers cache byte-identical prefixes; using
 76|         // the user-message position on the first run would make that first
 77|         // evidence miss the cache again on the next run.
 78|         let evidence = replay::render(input.diffs);
 79|         let (reviewed_evidence, new_evidence) = if input.reviewed_evidence.is_empty() {
 80|             (evidence.clone(), String::new())
 81|         } else {
 82|             replay::split(input.reviewed_evidence, &evidence)
 83|         };
 84|         let changed_paths = input.changed_paths();
 85|         let built = prompt::build(&PromptInputs {
 86|             repo_policy: input.repo_policy,
 87|             extracted_rules: input.extracted_rules,
 88|             reviewed_evidence: &reviewed_evidence,
 89|             prior_findings: input.prior_findings,
 90|             new_evidence: &new_evidence,
 91|             changed_paths: &changed_paths,
 92|             retrieved_context: input.retrieved_context,
 93|             ..PromptInputs::new(LaneId::Critique, input.config)
 94|         });
 95| 
 96|         // The prefix goes in the system message and the suffix in the user
 97|         // message. Providers cache on the serialised prefix, and a system
 98|         // message is the one part guaranteed to be sent first.
 99|         let response = self
100|             .model
101|             .complete(ModelRequest {
