  3| //! Two halves, and the order between them is the design:
  4| //!
  5| //! 1. The deterministic scanners have **already run**, before any token was
  6| //!    spent. Their findings are facts. This lane republishes them unchanged and
  7| //!    hands them to the model as evidence to *adjudicate* — say whether each is
  8| //!    real here and why — rather than asking a model to re-derive them. A
  9| //!    regular expression that finds a widened workflow permission is cheaper,
 10| //!    faster and more certain than a paragraph asking a model to look for one,
 11| //!    and duplicating the scanner in the prompt would produce two opinions
 12| //!    about one fact.
 13| //! 2. The model then looks for what a scanner cannot see: untrusted input
 14| //!    reaching a dangerous sink, an authorisation check that moved, a new
 15| //!    subprocess or deserialization site.
 16| //!
 17| //! A model verdict never *removes* a scanner finding. Adjudication adds
 18| //! context; it does not get to overrule a deterministic match, because the
 19| //! failure mode of a model talking itself out of a real finding is exactly the
 20| //! one this lane exists to prevent.
 21| //!
 22| //! It fans out one conversation per changed file — see `lanes::fanout` for why.
 23| 
 24| use std::fmt::Write as _;
 25| use std::sync::Arc;
 26| 
 27| use async_trait::async_trait;
 28| 
 29| use crate::config::types::LaneId;
 30| use crate::error::Result;
 31| use crate::evidence::diff::{FileDiff, render as render_diffs};
 32| use crate::findings::types::Finding;
 33| use crate::harness::prompt::{self, PromptInputs};
 34| use crate::harness::schema;
 35| use crate::lanes::fanout::{FileReview, per_file_with_budget};
 36| use crate::lanes::triage::triage;
 37| use crate::lanes::{Anchoring, Lane, LaneInput, LaneOutcome};
 38| use crate::ports::model::{Message, Model, ModelRequest, Spend};
 39| use crate::scan::types::{Finding as ScanFinding, ScanKind};
 40| 
 41| /// The scanner findings this lane owns.
 42| ///
 43| /// A partition, not an overlap: `commits` adjudicates secrets, blobs and junk,
 44| /// and two lanes discussing one scanner match would double-report it.
 45| pub const ADJUDICATES: [ScanKind; 2] = [ScanKind::Workflow, ScanKind::Dependency];
 46| 
 47| /// The security lane.
 48| pub struct Security {
 49|     model: Arc<dyn Model>,
 50| }
 51| 
 52| impl Security {
 53|     /// Build the lane over `model`.
 54|     pub fn new(model: Arc<dyn Model>) -> Self {
 55|         Self { model }
 56|     }
 57| }
 58| 
 59| #[async_trait]
 60| impl Lane for Security {
 61|     fn id(&self) -> LaneId {
 62|         LaneId::Security
 63|     }
 64| 
 65|     async fn run(&self, input: LaneInput<'_>) -> Result<LaneOutcome> {
 66|         let scanner = input.scanner_findings_of(&ADJUDICATES);
 67| 
 68|         // A scanner finding is reason enough to run even when nothing else is
 69|         // reviewable: a workflow whose only change is a widened permission
 70|         // still has to be reported.
 71|         if !input.has_reviewable_content() && scanner.is_empty() {
 72|             return Ok(LaneOutcome::skipped(
 73|                 "No added or modified lines to review.",
 74|             ));
 75|         }
 76| 
 77|         if let Some(skipped) = input.skip_as_draft() {
 78|             return Ok(skipped);
 79|         }
 80| 
 81|         // Files this lane has already seen, unchanged since. Dropped before
 82|         // triage, not after: the cheapest call is the one not made, and this
 83|         // lane spends one call per file, so re-reviewing an untouched file on
 84|         // every push is the single largest avoidable cost in a review.
 85|         //
 86|         // Distinct from replaying evidence into the cacheable prefix, which is
 87|         // what `critique` does. That only pays when the provider honours the
 88|         // cache; this pays always.
 89|         let fresh: Vec<crate::evidence::diff::FileDiff> =
 90|             crate::evidence::replay::unreviewed(input.reviewed_evidence, input.diffs)
 91|                 .into_iter()
 92|                 .cloned()
 93|                 .collect();
 94| 
 95|         // Deterministic triage before any token is spent: drop the files that
 96|         // cannot carry a vulnerability, and review what is left riskiest first
 97|         // so an exhausted budget was spent on the files that mattered.
 98|         //
 99|         // A scanner match forces its file back in even when unchanged: a
100|         // committed key is reported every time until it is gone, and "we
101|         // mentioned it last push" is not a reason to stop.
102|         let forced: Vec<&str> = scanner.iter().map(|f| f.path.as_str()).collect();
103|         let forced_back: Vec<crate::evidence::diff::FileDiff> = input
104|             .diffs
105|             .iter()
106|             .filter(|d| forced.contains(&d.path.as_str()))
107|             .filter(|d| !fresh.iter().any(|f| f.path == d.path))
108|             .cloned()
109|             .collect();
110|         let mut considered = fresh;
111|         considered.extend(forced_back);
112| 
113|         let triaged = triage(&considered, &forced);
114| 
115|         if triaged.review.is_empty() && scanner.is_empty() {
116|             return Ok(LaneOutcome::skipped(format!(
117|                 "No changed file has any attack surface.{}",
118|                 skip_note(&triaged.skipped)
119|             )));
120|         }
121| 
122|         let outcome = per_file_with_budget(
123|             &triaged.review,
124|             input.config.models.budget_usd_per_pr,
125|             |path| {
126|                 let model = self.model.clone();
127|                 let config = input.config;
128|                 let repo_policy = input.repo_policy;
129|                 let extracted_rules = input.extracted_rules;
130|                 let prior_findings = input.prior_findings;
131|                 let retrieved_context = input.retrieved_context;
132|                 let diffs = input.diffs;
133|                 let scanner = &scanner;
134|                 async move {
135|                     let diff = diffs
136|                         .iter()
137|                         .find(|d| d.path == path)
138|                         .expect("the path came from the diff list");
139|                     review_file(
140|                         model.as_ref(),
141|                         config,
142|                         repo_policy,
143|                         extracted_rules,
144|                         prior_findings,
145|                         retrieved_context,
146|                         diff,
147|                         scanner,
148|                     )
149|                     .await
150|                 }
151|             },
152|         )
153|         .await;
154| 
155|         let mut outcome = outcome.into_outcome();
156|         outcome.summary.push_str(&skip_note(&triaged.skipped));
157|         merge_scanner_findings(&mut outcome, &scanner);
158|         Ok(outcome)
159|     }
160| }
161| 
162| /// Review one file, in a conversation that knows about no other file.
163| ///
164| // Every argument is one prompt layer, and they are passed individually rather
165| // than as a context struct because each has a different trust level — see
166| // `harness::prompt`. Bundling them would make it easy to route the untrusted
167| // ones to the wrong half of the prompt.
168| #[allow(clippy::too_many_arguments)]
169| async fn review_file(
170|     model: &dyn Model,
171|     config: &crate::config::types::Config,
172|     repo_policy: Option<&str>,
173|     extracted_rules: &[String],
174|     prior_findings: &[String],
175|     retrieved_context: &str,
176|     diff: &FileDiff,
177|     scanner: &[&ScanFinding],
178| ) -> Result<FileReview> {
179|     let evidence = render_diffs(std::slice::from_ref(diff));
180|     let scanner_evidence = render_scanner(scanner, Some(&diff.path));
181| 
182|     let built = prompt::build(&PromptInputs {
183|         repo_policy,
184|         extracted_rules,
185|         prior_findings,
186|         new_evidence: &evidence,
187|         focus_path: Some(&diff.path),
188|         scanner_evidence: &scanner_evidence,
189|         retrieved_context,
190|         ..PromptInputs::new(LaneId::Security, config)
191|     });
192| 
193|     let response = model
194|         .complete(ModelRequest {
195|             model: config.model_for(LaneId::Security).to_string(),
196|             messages: vec![
197|                 Message::system(built.prefix()),
198|                 Message::user(built.suffix()),
199|             ],
200|             schema: schema::json_schema(),
201|             schema_name: "tinysweeper_security".into(),
202|             max_tokens: config.models.max_tokens,

